#include <bits/stdc++.h>
using namespace std;
class Solution {public:int longestSubsequence(string s,int k){int ans=count(s.begin(),s.end(),'0');long long value=0,place=1;for(int i=(int)s.size()-1;i>=0;--i){if(s[i]=='1'&&place<=k&&value+place<=k){value+=place;++ans;}if(place<=k)place*=2;}return ans;}};
